  "niveau_confiance": 100,
  "reclusteriser": false
}

{
  "action_centroide": "RAPPEL_CREER",
  "analyse_extremes": "Les verbes 'crée', 'programme', 'mets', 'configure', 'définis' sont des synonymes du déclenchement de CreateReminder via l'API Reminders. Les contenus des rappels sont des entités ignorables (Règle 3). Action de création identique. Pur.",
  "niveau_confiance": 100,
  "reclusteriser": false
}

{
  "action_centroide": "TRANSPORT_RESERVER",
  "analyse_extremes": "Toutes ces phrases exigent du système de lancer une transaction pour appeler/réserver un véhicule (AMAZON.BookAction) auprès de diverses Skills partenaires (Udrive, Uber, Taxi local). L'action est la même. Pur.",
  "niveau_confiance": 100,
  "reclusteriser": false
}

{
  "action_centroide": "BLAGUE_QUERY",
