  "niveau_confiance": 95,
  "reclusteriser": true
}

{
  "action_centroide": "CALENDRIER_QUERY",
  "analyse_extremes": "L'action système déclenchée pour toutes les phrases est la lecture des événements programmés dans l'agenda (AMAZON.SearchAction sur Calendar). Les notions temporelles sont gérées en paramètres. Pur.",
  "niveau_confiance": 100,
  "reclusteriser": false
